<?php
header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0');
try{require_once __DIR__.'/../Config/database.php';require_once __DIR__.'/../Config/mikrotik.php';$pdo=(new Database())->connect();$cfg=new MikroTikConfig();$router=$cfg->getRouter();$rid=(int)($router['id']??0);$where="created_at>=DATE_SUB(NOW(),INTERVAL 30 DAY) AND (LOWER(alarm_type) LIKE 'pppoe%' OR LOWER(interface_name) LIKE '%pppoe%')";$params=[];if($rid>0){$where.=' AND router_id=?';$params[]=$rid;}$st=$pdo->prepare("SELECT alarm_type,severity,status,interface_name,message,value,threshold,created_at,resolved_at FROM alarms WHERE {$where} ORDER BY created_at DESC");$st->execute($params);$rows=$st->fetchAll(PDO::FETCH_ASSOC);$users=[];foreach($rows as $r){$iface=trim((string)$r['interface_name']," <>\t\n\r\0\x0B");$u=null;if(preg_match('/^pppoe-(.+)$/i',$iface,$m))$u=$m[1];elseif(preg_match('/^PPPoE\s+(.+?)\s+(?:download|upload)\s+/i',(string)$r['message'],$m))$u=trim($m[1]);if(!$u)continue;if(!isset($users[$u]))$users[$u]=['username'=>$u,'total'=>0,'critical'=>0,'warning'=>0,'active'=>0,'download'=>0,'upload'=>0,'sum_ratio'=>0,'peak_ratio'=>0,'durations'=>[],'recent'=>[],'last_alarm'=>$r['created_at']];$x=&$users[$u];$x['total']++;$sev=strtolower((string)$r['severity']);if(isset($x[$sev]))$x[$sev]++;if(strtolower((string)$r['status'])==='active')$x['active']++;$type=strtolower((string)$r['alarm_type']);if(strpos($type,'download')!==false)$x['download']++;if(strpos($type,'upload')!==false)$x['upload']++;$v=(float)$r['value'];$t=(float)$r['threshold'];$ratio=$t>0?$v/$t:0;$x['sum_ratio']+=$ratio;$x['peak_ratio']=max($x['peak_ratio'],$ratio);if(count($x['recent'])<10)$x['recent'][]=$r;if(!empty($r['resolved_at'])){$a=strtotime($r['created_at']);$b=strtotime($r['resolved_at']);if($a&&$b&&$b>=$a)$x['durations'][]=($b-$a)/60;}unset($x);}foreach($users as &$x){$avg=$x['total']?$x['sum_ratio']/$x['total']:0;$dur=$x['durations']?array_sum($x['durations'])/count($x['durations']):0;$score=100-min(30,$x['total']*3)-min(25,$x['critical']*7)-min(15,$x['active']*10)-min(20,$avg*20)-min(10,$dur/10);$x['score']=max(0,min(100,round($score)));$x['health']=$x['score']>=80?'HEALTHY':($x['score']>=60?'WARNING':'CRITICAL');$x['avg_usage_percent']=round($avg*100,1);$x['peak_usage_percent']=round($x['peak_ratio']*100,1);$x['avg_duration_min']=round($dur,1);$x['trend']='STABLE';$x['early_warning']=null;$recent=$x['recent'];$cut=count($recent);if($cut>=2){$half=max(1,intdiv($cut,2));$new=array_slice($recent,0,$half);$old=array_slice($recent,$half);$nr=array_sum(array_map(fn($r)=>(float)$r['threshold']>0?(float)$r['value']/(float)$r['threshold']:0,$new))/count($new);$or=array_sum(array_map(fn($r)=>(float)$r['threshold']>0?(float)$r['value']/(float)$r['threshold']:0,$old))/count($old);if($nr>$or*1.15){$x['trend']='WORSENING';$x['early_warning']='Pemakaian alarm meningkat';}elseif($nr<$or*0.85){$x['trend']='IMPROVING';}}if($x['health']==='HEALTHY'&&$x['trend']==='WORSENING'&&$x['avg_usage_percent']>=65)$x['early_warning']='Potensi pelanggan bermasalah';unset($x['sum_ratio'],$x['peak_ratio'],$x['durations'],$x['recent']);}unset($x);usort($users,fn($a,$b)=>$a['score']<=>$b['score']);echo json_encode(['success'=>true,'period'=>'30d','router_id'=>$rid,'router_name'=>$router['router_name']??null,'users'=>array_values($users)],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);}catch(Throwable $e){http_response_code(500);echo json_encode(['success'=>false,'message'=>'Health score unavailable']);}
